AHB.audio({"groups": {"part-01-vocabulary": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-01-vocabulary/001.mp3", "text": "Al-Hasan is a big (1)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-01-vocabulary/002.mp3", "text": "It is a holding (2)… in six (3)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-01-vocabulary/003.mp3", "text": "It has got a head (4)… in Damascus and a (5)… in Aleppo."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-01-vocabulary/004.mp3", "text": "It sells products to (6)… in other countries."}], "title": "Read and listen"}], "part-02-grammar": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/001.mp3", "text": "We use the verb BE to say who and what things are."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/002.mp3", "text": "I am (I'm), you/we/they are (you're), he/she/it is (he's)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/003.mp3", "text": "Negative: I'm not, she isn't, we aren't."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/004.mp3", "text": "Questions: Am I"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/005.mp3", "text": "We use HAVE GOT to say what we have."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/006.mp3", "text": "I / you / we / they have got (I've got)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/007.mp3", "text": "He / she / it has got (she's got)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/008.mp3", "text": "The Group has got six sectors."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/009.mp3", "text": "We have got many partners."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/010.mp3", "text": "Questions: Have you got"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/011.mp3", "text": "We use the PRESENT SIMPLE for jobs, habits and facts."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/012.mp3", "text": "I / you / we / they work."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/013.mp3", "text": "He / she / it works (add -s)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/014.mp3", "text": "Questions: Do you work"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/015.mp3", "text": "Does she work"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/016.mp3", "text": "Negative: I don't work, she doesn't work."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/017.mp3", "text": "We use THERE IS for one thing (singular) and THERE ARE for many (plural)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/018.mp3", "text": "There is a factory in Aleppo."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/019.mp3", "text": "There are six sectors."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/020.mp3", "text": "Questions: Is there"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/021.mp3", "text": "We use some (+) and any (? / −): There are some offices."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/022.mp3", "text": "Is there any water?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/023.mp3", "text": "Add -s only for he / she / it: I work → she works."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/024.mp3", "text": "And use is with 'a/an/one', are with plurals: there IS an office."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/025.mp3", "text": "There ARE two factories."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-02-grammar/026.mp3", "text": "Don't say 'I have five years' for age — but for things, use 'have got': I have got a car."}], "title": "Read and listen"}], "part-03-listening": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-03-listening/001.mp3", "text": "Listen and read. (Your teacher will read the dialogue, or play the audio.)"}], "title": "Read and listen"}, {"clips": [{"ar": "", "speaker": "Mr. Tarek", "src": "../../assets/audio/unit-01/part-03-listening/002.mp3", "text": "Good morning, and welcome to Al-Hasan! I'm Tarek, the General Manager. Nice to meet you."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-03-listening/003.mp3", "text": "Thank you! I'm Ms. Chen, from NorthBridge. Nice to meet you too."}, {"ar": "", "speaker": "Mr. Tarek", "src": "../../assets/audio/unit-01/part-03-listening/004.mp3", "text": "Please, come in. Let me introduce the team. This is Karim, our Financial Controller."}, {"ar": "", "speaker": "Karim", "src": "../../assets/audio/unit-01/part-03-listening/005.mp3", "text": "Hello, Ms. Chen. Welcome. Nice to meet you."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-03-listening/006.mp3", "text": "Hello, Karim. Nice to meet you."}, {"ar": "", "speaker": "Mr. Tarek", "src": "../../assets/audio/unit-01/part-03-listening/007.mp3", "text": "And this is Huda, our Accountant, and Fadi, our Administrative Assistant."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-03-listening/008.mp3", "text": "Hello, everyone. You have got a beautiful office."}, {"ar": "", "speaker": "Mr. Tarek", "src": "../../assets/audio/unit-01/part-03-listening/009.mp3", "text": "Thank you. Please, sit down. Would you like some tea or coffee?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-03-listening/010.mp3", "text": "Tea, please. Thank you."}], "title": "Dialogue D1"}, {"clips": [{"ar": "", "speaker": "Karim", "src": "../../assets/audio/unit-01/part-03-listening/011.mp3", "text": "Hello, this is Karim from Al-Hasan Holding Group. How are you?"}, {"ar": "", "speaker": "Partner", "src": "../../assets/audio/unit-01/part-03-listening/012.mp3", "text": "Hello, Karim. I'm fine, thank you. And you?"}, {"ar": "", "speaker": "Karim", "src": "../../assets/audio/unit-01/part-03-listening/013.mp3", "text": "Very well, thank you. I have got some information about our products."}, {"ar": "", "speaker": "Partner", "src": "../../assets/audio/unit-01/part-03-listening/014.mp3", "text": "Great. Are you the manager?"}, {"ar": "", "speaker": "Karim", "src": "../../assets/audio/unit-01/part-03-listening/015.mp3", "text": "No, I'm the Financial Controller. Mr. Tarek is the General Manager."}, {"ar": "", "speaker": "Partner", "src": "../../assets/audio/unit-01/part-03-listening/016.mp3", "text": "I see. Thank you, Karim. Have a good day."}, {"ar": "", "speaker": "Karim", "src": "../../assets/audio/unit-01/part-03-listening/017.mp3", "text": "You too. Goodbye."}], "title": "Dialogue D2"}], "part-04-speaking": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-04-speaking/001.mp3", "text": "A: Greet the visitor ('Good morning, welcome!')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-04-speaking/002.mp3", "text": "B: Say your name and company ('I'm…, from…')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-04-speaking/003.mp3", "text": "A: Say your name and job ('I'm…, the…')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-04-speaking/004.mp3", "text": "A: Introduce a colleague ('This is…, our…')."}], "title": "Read and listen"}], "part-05-reading": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/001.mp3", "text": "Al-Hasan is a 'holding group'."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/002.mp3", "text": "What does this mean?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/003.mp3", "text": "A holding group is one big company."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/004.mp3", "text": "Inside it, there are many smaller companies."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/005.mp3", "text": "Each small company does one job."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/006.mp3", "text": "Together, they are strong."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/007.mp3", "text": "Al-Hasan has got many companies."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/008.mp3", "text": "For example, one company makes cement."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/009.mp3", "text": "One company makes iron."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/010.mp3", "text": "One company moves the goods by ship and truck."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/011.mp3", "text": "And one company buys and sells products in other countries."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/012.mp3", "text": "Each company is different, but they all work together, in one group."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/013.mp3", "text": "This is good for business."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/014.mp3", "text": "When one company needs cement, another company in the group can make it."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/015.mp3", "text": "When goods must travel abroad, the transport company can help."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/016.mp3", "text": "The companies help each other."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/017.mp3", "text": "This is the power of a holding group: many companies, one team."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/018.mp3", "text": "Al-Hasan works in six sectors: industry, trade, energy, construction, tourism, and services."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/019.mp3", "text": "It is in Damascus, in Syria."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/020.mp3", "text": "Its motto is 'Solid Values… Unlimited Ambitions'."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/021.mp3", "text": "Today, the Group works with partners all over the world."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/022.mp3", "text": "It buys and sells products, and it builds new projects."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/023.mp3", "text": "For the people who work there, every day is busy — and every day is different."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/024.mp3", "text": "A holding (1)… is one big company with many (2)… companies inside."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/025.mp3", "text": "The companies (3)… each other."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/026.mp3", "text": "Al-Hasan works in six (4)… and is in (5)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-05-reading/027.mp3", "text": "It works with (6)… all over the world."}], "title": "Read and listen"}], "part-06-writing": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-06-writing/001.mp3", "text": "Sentence starters: “Dear …,” · “My name is"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-06-writing/002.mp3", "text": "I am the …” · “We make …” · “We have got …” · “Best regards, …”"}], "title": "Read and listen"}], "part-07-trade-skills": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-07-trade-skills/001.mp3", "text": "Every company has got a structure — this shows who does what."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-07-trade-skills/002.mp3", "text": "At the top is the Founder, Mr. Adnan."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-07-trade-skills/003.mp3", "text": "Below him is the Board, and the General Manager, Mr. Tarek."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-07-trade-skills/004.mp3", "text": "Then there are the departments."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-07-trade-skills/005.mp3", "text": "In Finance, Karim and Lina work with money and prices."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-07-trade-skills/006.mp3", "text": "In Accounts, Huda checks the invoices."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-07-trade-skills/007.mp3", "text": "In Admin, Fadi arranges meetings and emails."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-07-trade-skills/008.mp3", "text": "And in Logistics, the team arranges delivery."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-07-trade-skills/009.mp3", "text": "When you know the structure, you know who to ask."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-07-trade-skills/010.mp3", "text": "If you have a question about money, you ask Finance."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-07-trade-skills/011.mp3", "text": "If you have a question about an invoice, you ask the Accountant."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-07-trade-skills/012.mp3", "text": "If you want a meeting, you ask the Admin Assistant."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-07-trade-skills/013.mp3", "text": "A good team knows its structure — and it works together."}], "title": "Read and listen"}], "part-08-consolidation": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/001.mp3", "text": "At the end of the day, Ms. Chen is happy."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/002.mp3", "text": "She knows the whole team now."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/003.mp3", "text": "She knows Mr. Adnan, the Founder, and Mr. Tarek, the General Manager."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/004.mp3", "text": "She knows Karim in Finance, Huda in Accounts, and Fadi in Admin."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/005.mp3", "text": "Everyone is friendly, and everyone speaks some English."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/006.mp3", "text": "“Thank you for a very good day,” Ms. Chen says."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/007.mp3", "text": "“You are a good team, and Al-Hasan is a good company."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/008.mp3", "text": "I think NorthBridge and Al-Hasan can work well together.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/009.mp3", "text": "Mr. Tarek is happy too."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/010.mp3", "text": "“Thank you, Ms. Chen."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/011.mp3", "text": "We are very happy to meet you."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/012.mp3", "text": "Next week, we can talk about products and prices.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/013.mp3", "text": "Ms. Chen goes home."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/014.mp3", "text": "Karim writes her a short email: 'Dear Ms. Chen, thank you for your visit."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/015.mp3", "text": "It was very nice to meet you."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/016.mp3", "text": "Best regards, Karim.'"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/017.mp3", "text": "A small email, but an important one — because a good partnership starts with a good hello."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/018.mp3", "text": "“That is the first step,” thinks Karim."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/019.mp3", "text": "“We said hello."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-08-consolidation/020.mp3", "text": "Now the work begins.”"}], "title": "Read and listen"}], "part-09-cases": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-09-cases/001.mp3", "text": "A partner arrives at your office for the first time."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-09-cases/002.mp3", "text": "You are at reception."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-09-cases/003.mp3", "text": "What do you say and do first?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-09-cases/004.mp3", "text": "Write one sentence to welcome the visitor."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-09-cases/005.mp3", "text": "The visitor meets your team of three people."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-09-cases/006.mp3", "text": "You must introduce them."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-09-cases/007.mp3", "text": "You forget the visitor's name."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-09-cases/008.mp3", "text": "You are not sure — is it Ms. Chen or Ms. Chan?"}], "title": "Read and listen"}], "part-10-review": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-10-review/001.mp3", "text": "Al-Hasan is a holding group in Damascus."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-10-review/002.mp3", "text": "It has got many companies and works in six sectors."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-10-review/003.mp3", "text": "Karim is the Financial Controller."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-10-review/004.mp3", "text": "Ms. Chen is from NorthBridge, a partner in another country."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-10-review/005.mp3", "text": "There are factories in Aleppo and offices in Damascus."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-10-review/006.mp3", "text": "[Teacher reads] 'Good morning, and welcome!"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-10-review/007.mp3", "text": "I'm Tarek, the General Manager."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-10-review/008.mp3", "text": "This is Karim, our Financial Controller."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-10-review/009.mp3", "text": "We have got six sectors, and we make cement, iron and steel.'"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-10-review/010.mp3", "text": "I can describe my company and my department."}], "title": "Read and listen"}], "part-11-foundations": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/001.mp3", "text": "In this unit, you learned a big idea in business: the holding group."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/002.mp3", "text": "It is a simple but powerful idea."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/003.mp3", "text": "Instead of one company doing everything, a holding group has many companies, and each one does one thing well."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/004.mp3", "text": "One company makes cement."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/005.mp3", "text": "One company makes iron."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/006.mp3", "text": "One company (Komosh) moves the goods."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/007.mp3", "text": "One company (Bashak) buys and sells abroad."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/008.mp3", "text": "Each is an expert in its own job."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/009.mp3", "text": "Why is this a good idea?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/010.mp3", "text": "First, each company can be very good at one thing."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/011.mp3", "text": "The cement company thinks only about cement, so it makes very good cement."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/012.mp3", "text": "Second, the companies help each other."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/013.mp3", "text": "When Bashak needs cement to sell abroad, the cement company can make it."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/014.mp3", "text": "When the goods must travel, Komosh can move them."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/015.mp3", "text": "They are like the players in a football team."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/016.mp3", "text": "Each player has a job."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/017.mp3", "text": "They all play together, and together they are strong."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/018.mp3", "text": "This idea — many small parts working together as one — is everywhere in business and in life."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/019.mp3", "text": "A big company has departments."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/020.mp3", "text": "A city has many services."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/021.mp3", "text": "A team has many people."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/022.mp3", "text": "When you understand how the parts fit together, you understand the whole."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/023.mp3", "text": "So as you learn English for your work, remember: you are not just one person doing one job."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/024.mp3", "text": "You are part of a team, part of a group, part of something big."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/025.mp3", "text": "When you can talk about your company and your team in English, you can help."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/026.mp3", "text": "You help the whole group work with the world."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/027.mp3", "text": "Think about your own company or team."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/028.mp3", "text": "What are the different parts (departments or jobs)?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/029.mp3", "text": "How do they help each other?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/030.mp3", "text": "Draw it and explain it in simple English."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/031.mp3", "text": "Write a few sentences (30–50 words) about your company."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/032.mp3", "text": "Use 'be', 'have got' and 'there is/are'."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/033.mp3", "text": "Example: 'My company is"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/part-11-foundations/034.mp3", "text": "There are …'"}], "title": "Read and listen"}], "warm-up": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/001.mp3", "text": "Look at the pictures."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/002.mp3", "text": "Answer these questions before you read."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/003.mp3", "text": "Welcome to Al-Hasan Holding Group."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/004.mp3", "text": "It is a big company in Damascus, in Syria."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/005.mp3", "text": "It is a 'holding group' — this means it has got many smaller companies inside it."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/006.mp3", "text": "The Group works in six sectors: industry, trade, energy, construction, tourism, and services."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/007.mp3", "text": "Karim works at Al-Hasan."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/008.mp3", "text": "He is the Financial Controller."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/009.mp3", "text": "“I like my job,” he says."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/010.mp3", "text": "“Every day is different.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/011.mp3", "text": "The Group makes and sells industrial and construction products — cement, iron, and steel."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/012.mp3", "text": "It sells these products to partners in other countries."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/013.mp3", "text": "Today is an important day."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/014.mp3", "text": "A new partner visits us today."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/015.mp3", "text": "Her name is Ms. Chen, and she is from NorthBridge Industrial Trading, a company in another country."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/016.mp3", "text": "NorthBridge wants to buy cement and iron from Al-Hasan."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/017.mp3", "text": "The team is ready."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/018.mp3", "text": "Mr. Adnan is the Founder."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/019.mp3", "text": "Mr. Tarek is the General Manager."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/020.mp3", "text": "Karim is the Financial Controller."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/021.mp3", "text": "Lina is the Financial Manager."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/022.mp3", "text": "Huda is the Accountant."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/023.mp3", "text": "And Fadi is the Administrative Assistant."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/024.mp3", "text": "They are a good team, and they all speak some English."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/025.mp3", "text": "“Good morning, and welcome!” says Mr. Tarek."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/026.mp3", "text": "“I am Tarek, the General Manager."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/027.mp3", "text": "Nice to meet you.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/028.mp3", "text": "“Nice to meet you too,” says Ms. Chen."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/029.mp3", "text": "“This is a beautiful office.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/030.mp3", "text": "“Thank you,” says Mr. Tarek."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/031.mp3", "text": "“Let me introduce the team.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/032.mp3", "text": "One by one, the team say hello."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/033.mp3", "text": "“Hello, I'm Karim."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/034.mp3", "text": "I'm the Financial Controller.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/035.mp3", "text": "“Hello, I'm Huda."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/036.mp3", "text": "I'm the Accountant.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/037.mp3", "text": "Ms. Chen is happy."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/038.mp3", "text": "“It is very nice to meet you all,” she says."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/039.mp3", "text": "“I think we can do good business together.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-01/warm-up/040.mp3", "text": "And so, a new partnership begins."}], "title": "Read and listen"}]}, "unit": 1});
